import os
import queue
from typing import Iterator, Optional

from google.cloud import speech_v1 as speech


class StreamingSpeechRecognizer:
    def __init__(
        self,
        language_code: str = "en-US",
        enable_automatic_punctuation: bool = True,
        sample_rate_hertz: int = 16000,
        encoding: speech.RecognitionConfig.AudioEncoding = speech.RecognitionConfig.AudioEncoding.LINEAR16,
        interim_results: bool = True,
        credentials_path: Optional[str] = None,
    ) -> None:
        if credentials_path:
            os.environ["GOOGLE_APPLICATION_CREDENTIALS"] = credentials_path

        self.client = speech.SpeechClient()
        self._audio_queue: "queue.Queue[Optional[bytes]]" = queue.Queue()
        self._closed = False

        self.streaming_config = speech.StreamingRecognitionConfig(
            config=speech.RecognitionConfig(
                encoding=encoding,
                sample_rate_hertz=sample_rate_hertz,
                language_code=language_code,
                enable_automatic_punctuation=enable_automatic_punctuation,
            ),
            interim_results=interim_results,
        )

    def push_audio(self, chunk: bytes) -> None:
        if self._closed:
            raise RuntimeError("Recognizer is closed.")
        if not isinstance(chunk, (bytes, bytearray)):
            raise TypeError("Audio chunk must be bytes.")
        self._audio_queue.put(bytes(chunk))

    def close(self) -> None:
        if not self._closed:
            self._closed = True
            self._audio_queue.put(None)

    def _request_stream(self) -> Iterator[speech.StreamingRecognizeRequest]:
        while True:
            chunk = self._audio_queue.get()
            if chunk is None:
                break
            yield speech.StreamingRecognizeRequest(audio_content=chunk)

    def start(self) -> Iterator[dict]:
        responses = self.client.streaming_recognize(
            config=self.streaming_config,
            requests=self._request_stream(),
        )

        for response in responses:
            for result in response.results:
                if not result.alternatives:
                    continue
                alt = result.alternatives[0]
                yield {
                    "transcript": alt.transcript,
                    "confidence": getattr(alt, "confidence", 0.0),
                    "is_final": result.is_final,
                    "language_code": self.streaming_config.config.language_code,
                }
